5ccc004cbe'),(212,10,'collage_image_5','378'),(213,10,'_collage_image_5','field_6465ccc904cbf'),(214,10,'collage_content_1','<p><span style=\"font-weight: 400;\">Pulang Villas was initially designed as a vacation home, with interiors and design elements that reflect the owner\'s personal taste. Each villa features unique artwork and puzzle paintings created by the owner\'s children, adding a personal and creative touch to the luxurious ambiance. These thoughtful design elements, combined with modern amenities, ensure a harmonious getaway for every guest.</span></p>'),(215,10,'_collage_content_1','field_6465cec18ad32'),(216,10,'collage_content_2','<p><span style=\"font-weight: 400;\">The name \"Pulang,\" meaning \"home\" in Indonesian, perfectly captures the warm, welcoming atmosphere we intend for our guests to experience. From the beautifully landscaped gardens to the inviting living spaces, every detail of Pulang Villas is designed to make you feel at home. Whether you\'re relaxing by the private overflow pool, enjoying the spacious living areas, or exploring the local attractions, Pulang Villas offers the ideal setting for a memorable stay.</span></p>'),(217,10,'_collage_content_2','field_6465cec98ad33'),(218,10,'features_image_1',''),(219,10,'_features_image_1','field_6465ced28ad34'),(220,10,'features_image_2',''),(221,10,'_features_image_2','field_6465ceee8ad35'),(222,10,'features_image_3',''),(223,10,'_features_image_3','field_6465cf5cfb457'),(224,257,'_wp_attached_file','2024/08/home-pool-min.jpg'),(225,257,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:1420;s:6:\"height\";i:720;s:4:\"file\";s:25:\"2024/08/home-pool-min.jpg\";s:8:\"filesize\";i:220565;s:5:\"sizes\";a:5:{s:6:\"medium\";a:5:{s:4:\"file\";s:25:\"home-pool-min-300x152.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:152;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:13353;}s:5:\"large\";a:5:{s:4:\"file\";s:26:\"home-pool-min-1024x519.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:519;s:9:\"mime