living spaces, every detail of Pulang Villas is designed to make you feel at home. Whether you\'re relaxing by the private overflow pool, enjoying the spacious living areas, or exploring the local attractions, Pulang Villas offers the ideal setting for a memorable stay.</span></p>'),(1462,502,'_collage_content_2','field_6465cec98ad33'),(1463,502,'features_image_1',''),(1464,502,'_features_image_1','field_6465ced28ad34'),(1465,502,'features_image_2',''),(1466,502,'_features_image_2','field_6465ceee8ad35'),(1467,502,'features_image_3',''),(1468,502,'_features_image_3','field_6465cf5cfb457'),(1469,507,'_edit_last','1'),(1470,507,'field_682b0082aaf1c','a:11:{s:3:\"key\";s:19:\"field_682b0082aaf1c\";s:5:\"label\";s:14:\"Header Setting\";s:4:\"name\";s:14:\"header_setting\";s:4:\"type\";s:8:\"checkbox\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";s:1:\"0\";s:7:\"choices\";a:2:{s:8:\"bg-white\";s:5:\"White\";s:0:\"\";s:11:\"Transparant\";}s:13:\"default_value\";s:0:\"\";s:6:\"layout\";s:8:\"vertical\";s:17:\"conditional_logic\";a:3:{s:6:\"status\";s:1:\"0\";s:5:\"rules\";a:1:{i:0;a:2:{s:5:\"field\";s:4:\"null\";s:8:\"operator\";s:2:\"==\";}}s:8:\"allorany\";s:3:\"all\";}s:8:\"order_no\";i:0;}'),(1471,507,'rule','a:5:{s:5:\"param\";s:9:\"post_type\";s:8:\"operator\";s:2:\"==\";s:5:\"value\";s:4:\"page\";s:8:\"order_no\";i:0;s:8:\"group_no\";i:0;}'),(1472,507,'rule','a:5:{s:5:\"param\";s:4:\"page\";s:8:\"operator\";s:2:\"==\";s:5:\"value\";s:3:\"487\";s:8:\"order_no\";i:0;s:8:\"group_no\";i:1;}'),(1473,507,'position','normal'),(1474,507,'layout','no_box'),(1475,507,'hide_on_screen',''),(1476,507,'_edit_lock','1747649807:1'),(1477,508,'header_setting','a:1:{i:0;s:0:\"\";}'),(1478,508,'_header_setting','field_682b0082aaf1c'),(1479,509,'header_setting','a:1:{i:0;s:0:\"\";}'),(1480,509,'_header_setting','field_682b0082aaf1c'),(1485,519,'_wp_attached_file','2025/06/thumb-breakfast.webp'),(1486,519,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:342;s:6:\"height\";i:369;s:4:\"