--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wp_posts` (
  `ID` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint(20) unsigned NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(255) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=549 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2024-04-09 04:06:33','2024-04-09 04:06:33','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2024-04-09 04:06:33','2024-04-09 04:06:33','',0,'https://pulangbali.com/?p=1',0,'post','',0),(2,1,'2024-04-09 04:06:33','2024-04-09 04:06:33','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"https://pulangbali.com/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','draft','closed','closed','','sample-page','','','2024-05-16 08:55:23','2024-05-16 08:55:23','',0,'https://pulangbali.com/?page_id=2',0,'page','',0),(3,1,'2024-04-09 04:06:33','2024-04-09 04:06:33','<!-- wp:heading --><h2>Who we are</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: https://pulangbali.com.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>Comments</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>Media</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>Cookies</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>Embedded content from other websites</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>Who we share your data with</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>How long we retain your data</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>What rights you have over your data</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p><!-- /wp:paragraph --><!-- wp:heading --><h2>Where your data is sent</h2><!-- /wp:heading --><!-- wp:paragraph --><p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p><!-- /wp:paragraph -->','Privacy Policy','','draft','closed','closed','','privacy-policy','','','2024-05-16 08:55:18','2024-05-16 08:55:18','',0,'https://pulangbali.com/?page_id=3',0,'page','',0),(5,0,'2024-04-09 04:12:42','2024-04-09 04:12:42','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2024-04-09 04:12:42','2024-04-09 04:12:42','',0,'https://pulangbali.com/2024/04/09/navigation/',0,'wp_navigation','',0),(7,1,'2024-04-09 04:19:18','2024-04-09 04:19:18','','Main Logo Villa Pulang','','inherit','open','closed','','main-logo-villa-pulang','','','2024-04-09 04:19:18','2024-04-09 04:19:18','',0,'https://pulangbali.com/wp-content/uploads/2024/04/Main-Logo-Villa-Pulang.png',0,'attachment','image/png',0),(10,1,'2024-05-10 03:30:28','2024-05-10 03:30:28','<!-- wp:paragraph -->\n<p>Nestled within the vibrant area of Pererenan, this 2-bedroom villa is part of the Pulang Villas complex, a collection of 10 exquisite villas in Canggu, perfect for families or groups of friends. Offering a blend of comfort and modern elegance.</p>\n<!-- /wp:paragraph -->','Home-old','','draft','closed','closed','','home-old','','','2025-05-19 08:41:34','2025-05-19 08:41:34','',0,'https://pulangbali.com/?page_id=10',0,'page','',0),(11,1,'2024-05-10 03:30:28','2024-05-10 03:30:28','<!-- wp:paragraph -->\n<p>Welcome to pulang bali by Nakula</p>\n<!-- /wp:paragraph -->','Home','','inherit','closed','closed','','10-revision-v1','','','2024-05-10 03:30:28','2024-05-10 03:30:28','',10,'https://pulangbali.com/?p=11',0,'revision','',0),(22,1,'2024-05-14 09:43:30','2024-05-14 09:43:30','','Pages','','publish','closed','closed','','page','','','2024-05-14 09:47:24','2024-05-14 09:47:24','',0,'https://pulangbali.com/?post_type=_pods_pod&#038;p=22',0,'_pods_pod','',0),(23,1,'2024-05-14 09:43:30','2024-05-14 09:43:30','','Stay','','publish','closed','closed','','stay','','','2024-05-14 09:47:24','2024-05-14 09:47:24','',22,'https://pulangbali.com/?post_type=_pods_group&#038;p=23',0,'_pods_group','',0),(24,1,'2024-05-14 09:45:20','2024-05-14 09:45:20','Detail of Villa Quick Fact','Quick Fact','','publish','closed','closed','','quick_fact','','','2024-05-14 09:47:24','2024-05-14 09:47:24','',22,'https://pulangbali.com/?post_type=_pods_field&#038;p=24',0,'_pods_field','',0),(25,1,'2024-05-14 09:48:20','2024-05-14 09:48:20','page-stay.php','','','publish','closed','closed','','25','','','2024-05-14 09:48:20','2024-05-14 09:48:20','',0,'https://pulangbali.com/?post_type=_pods_template&#038;p=25',0,'_pods_template','',0),(26,1,'2024-05-14 09:48:20','2024-05-14 09:48:20','page-stay.php','','','inherit','closed','closed','','25-revision-v1','','','2024-05-14 09:48:20','2024-05-14 09:48:20','',25,'https://pulangbali.com/?p=26',0,'revision','',0),(28,1,'2024-05-14 10:07:55','0000-00-00 00:00:00','','Page','','draft','closed','closed','','','','','2024-05-14 10:07:55','2024-05-14 10:07:55','',0,'https://pulangbali.com/?post_type=_pods_template&#038;p=28',0,'_pods_template','',0),(29,1,'2024-05-15 01:53:15','2024-05-15 01:53:15','<!-- wp:html -->\n<section class=\"mt-60\" data-aos=\"fade-up\">\n    <div class=\"container py-3\">\n        <div class=\"row\">\n            <div class=\"col-12 col-md-9\">\n            <h2 class=\"text-blue\">Villa Pulang 2BR</h2>\n            </div>\n        </div>\n    </div>\n    <div class=\"carousel\" data-flickity=\"{&quot;contain&quot;: true, &quot;groupCells&quot;: false, &quot;pageDots&quot;: false, &quot;imagesLoaded&quot;: true, &quot;imagesLoaded&quot;: true}\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/10/OUTDOOR-3.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/10/MASTER-BEDROOM2.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/10/MASTER-BEDROOM-1.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/10/LIVING-SPACE-DINING.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/10/KITCHEN-DINING-LIVING-SPACE.jpg\" width=\"660\" alt=\"image of room\">\n    </div>\n    <div class=\"container py-5\">\n        <div class=\"row\">\n            <div class=\"col-12 col-md-6 order-lg-2 ps-md-5\">                \n                <h3 class=\"text-blue\">The Property</h3>\n                <p>The two bedroom villas have an enclosed living room, kitchen and dining areas. You will also enjoy a swimming pool and pool deck just next to the dining area. Upstairs you will find an informal, getaway lounge, and the two bedrooms.</p>\n                <a class=\"btn btn-outline-red rounded-0 d-none d-lg-inline-block\" href=\"/room/pulang-villas-2br/\">See more</a>    \n            </div>\n            <div class=\"col-12 col-md-6 order-lg-1\">\n                <h3 class=\"text-blue facilities\"><span>Facilities</span></h3>\n                <div class=\"row row-cols-1 row-cols-sm-3 row-cols-md-3 row-cols-lg-3 g-2\">\n                    <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-size flex-shrink-0 me-3\"></i>\n                <div>260 m2</div>\n                </div>\n                <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-wifi flex-shrink-0 me-3\"></i>\n                <div>Free WiFi</div>\n                </div>\n                <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-pool flex-shrink-0 me-3\"></i>\n                <div>Private Pool</div>\n                </div>\n                <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-coffee flex-shrink-0 me-3\"></i>\n                <div>Breakfast Included</div>\n                </div>\n                </div>\n                <a class=\"btn btn-outline-red rounded-0 d-lg-none\" href=\"/room/pulang-villas-2br/\">See more</a>\n            </div>\n        </div>\n    </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<section class=\"mt-60\" data-aos=\"fade-up\">\n    <div class=\"container py-3\">\n        <div class=\"row\">\n            <div class=\"col-12 col-md-9\">\n            <h2 class=\"text-blue\">Villa Pulang 3BR</h2>\n            </div>\n        </div>\n    </div>\n    <div class=\"carousel\" data-flickity=\"{&quot;contain&quot;: true, &quot;groupCells&quot;: false, &quot;pageDots&quot;: false, &quot;imagesLoaded&quot;: true, &quot;imagesLoaded&quot;: true}\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/08/DSC03066-min.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/08/3brvilla-pulang-2-min.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/08/DINING-AREA-2-min.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/08/DINING-min.jpg\" width=\"660\" alt=\"image of room\">\n        <img class=\"img-fluid pe-1\" src=\"https://pulangbali.com/wp-content/uploads/2024/08/3brvilla-pulang-1-min.jpg\" width=\"660\" alt=\"image of room\">\n    </div>\n    <div class=\"container py-5\">\n        <div class=\"row\">\n            <div class=\"col-12 col-md-6 order-lg-2 ps-md-5\">                \n                <h3 class=\"text-blue\">The Property</h3>\n                <p>The three bedroom villa includes an enclosed living room, kitchen and dining areas, perfect for both relaxation and entertaining. Upstairs, you will find an additional large family room if you need some private time. It is set in a peaceful riverside location with tall trees. Step outside to enjoy a large outdoor swimming pool, complete with a pool deck, lounge chairs and a beautifully landscaped garden, offering a serene space to unwind.</p>\n                <a class=\"btn btn-outline-red rounded-0 d-none d-lg-inline-block\" href=\"/room/pulang-villas-3br\">See more</a>    \n            </div>\n            <div class=\"col-12 col-md-6 order-lg-1\">\n                <h3 class=\"text-blue facilities\"><span>Facilities</span></h3>\n                <div class=\"row row-cols-1 row-cols-sm-3 row-cols-md-3 row-cols-lg-3 g-2\">\n                    <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-size flex-shrink-0 me-3\"></i>\n                <div>380 m2</div>\n                </div>\n                <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-wifi flex-shrink-0 me-3\"></i>\n                <div>Free WiFi</div>\n                </div>\n                <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-pool flex-shrink-0 me-3\"></i>\n                <div>Private Pool</div>\n                </div>\n                <div class=\"col d-flex align-items-start mb-3\"><i class=\"ic-coffee flex-shrink-0 me-3\"></i>\n                <div>Breakfast Included</div>\n                </div>\n                </div>\n                <a class=\"btn btn-outline-red rounded-0 d-lg-none\" href=\"/room/pulang-villas-3br/\">See more</a>\n            </div>\n        </div>\n    </div>\n</section>\n<!-- /wp:html -->','Stay 3 Bedrooms','The villas are just a 10-minute walk to the popular Pererenan surfing beach. You’ll also find a variety of restaurants, bakeries, cafes and retail shops nearby, making it easy to explore the local culinary and social scene.<br>','draft','closed','closed','','stay-3-br','','','2025-03-11 02:27:38','2025-03-11 02:27:38','',0,'https://pulangbali.com/?page_id=29',0,'page','',0),(30,1,'2024-05-15 01:53:15','2024-05-15 01:53:15','','Stay','','inherit','closed','closed','','29-revision-v1','','','2024-05-15 01:53:15','2024-05-15 01:53:15','',29,'https://pulangbali.com/?p=30',0,'revision','',0),(32,1,'2024-05-15 02:27:05','2024-05-15 02:27:05','<!-- wp:shortcode -->\n<div id=\"butler\" data-aos=\"fade-up\">[experiencenew highlight_id=\"304\"]</div>\n<!-- /wp:shortcode -->\n\n<!-- wp:shortcode -->\n<div id=\"dining\" data-aos=\"fade-up\">[experiencenew2 highlight_id=\"306\"]</div>\n<!-- /wp:shortcode -->\n\n<!-- wp:shortcode -->\n<div id=\"wellness\" data-aos=\"fade-up\">[experiencenew highlight_id=\"309\"]</div>\n<!-- /wp:shortcode -->\n\n<!-- wp:shortcode -->\n<div id=\"activities\" data-aos=\"fade-up\">[experiencenew2 highlight_id=\"311\"]</div>\n<!-- /wp:shortcode -->','Experience','','publish','closed','closed','','experiences','','','2024-10-02 06:55:28','2024-10-02 06:55:28','',0,'https://pulangbali.com/?page_id=32',0,'page','',0),(33,1,'2024-05-15 02:27:05','2024-05-15 02:27:05','','Experience','','inherit','closed','